[data-bs-theme="light"] {
  // Note: Custom variable values only support SassScript inside `#{}`.

  // Colors
  //
  // Generate palettes for full colors, grays, and theme colors.

  --#{$prefix}body-color: #{$body-color};
  --#{$prefix}body-color-rgb: #{to-rgb($body-color)};
  --#{$prefix}body-bg: #{$body-bg};
  --#{$prefix}body-bg-rgb: #{to-rgb($body-bg)};

  --#{$prefix}emphasis-color: #{$body-emphasis-color};
  --#{$prefix}emphasis-color-rgb: #{to-rgb($body-emphasis-color)};

  --#{$prefix}secondary-color: #{$body-secondary-color};
  --#{$prefix}secondary-bg: #{$body-secondary-bg};
  --#{$prefix}tertiary-color: #{$body-tertiary-color};
  --#{$prefix}tertiary-bg: #{$body-tertiary-bg};

  // Note: --bs-body-color IS generated here, but its usage
  // is limited to the <body> element and elements that explicitly
  // reference var(--bs-body-color). Most Bootstrap components
  // compile their colors from Sass variables at build time,
  // so the CSS custom property is effectively decorative
  // for component-level text colors.

  @each $color, $value in $theme-colors {
    --#{$prefix}#{$color}: #{$value};
    --#{$prefix}#{$color}-rgb: #{to-rgb($value)};
  }

// bslib card component overrides
//
// These styles extend Bootstrap's .card component with bslib-specific
// features like fill behavior, sidebar integration, etc.

.bslib-card {
  // Card inherits Bootstrap's .card styles
  // Bootstrap .card sets:
  //   color: var(--#{$prefix}card-color)   (from _card-variables.scss)
  //   where $card-color: null !default      (i.e., not set)
  //
  // When $card-color is null, Bootstrap falls back to:
  //   color: var(--#{$prefix}body-color)    (in BS5.3+)
  //   color: $card-color or inherit          (in BS5.0-5.2)
  //
  // THE GAP: In BS5.0-5.2 (which bslib currently ships),
  // the fallback is `inherit`, which works for <body> children
  // but NOT for cards rendered inside components that set
  // their own color (e.g., .navbar wrapping a card).
  //
  // Additionally, bslib value boxes and other custom components
  // often set explicit colors that bypass the cascade entirely.

  &.bslib-card-fill {
    flex: 1 1 auto;
    min-height: 0;
  }

  .card-header {
    // Header text doesn't use $body-color
    // It uses $card-cap-color, which defaults to null (inherit)
    // This means header text color depends on DOM hierarchy
    font-weight: 500;
  }

  .card-body {
    // Card body text color comes from .card's color,
    // NOT directly from $body-color or --bs-body-color
    padding: $card-spacer-y $card-spacer-x;
  }

  .card-footer {
    border-top: $card-border-width solid $card-border-color;
  }
}
